// Structured security logging with log-injection defenses (JSON logs + control-char stripping)

import pino from "pino";
import crypto from "crypto";

type SecurityEventType =
  | "auth.login.success"
  | "auth.login.failure"
  | "access.denied"
  | "validation.failed";

type SecurityEvent = {
  type: SecurityEventType;
  ts: string;                 // ISO timestamp
  requestId?: string;
  sessionId?: string;
  userId?: string;
  username?: string;          // avoid if sensitive in your context
  ip?: string;
  userAgent?: string;
  route?: string;
  method?: string;
  status?: number;
  reason?: string;            // sanitized
  fields?: string[];          // validation fields
  meta?: Record<string, unknown>;
};

const logger = pino({
  level: process.env.LOG_LEVEL ?? "info",
  // Ensure logs are single-line JSON; avoid printf-style logs.
  base: { service: process.env.SERVICE_NAME ?? "webapp" },
  redact: {
    paths: [
      "req.headers.authorization",
      "req.headers.cookie",
      "meta.password",
      "meta.token",
      "meta.secret",
    ],
    remove: true,
  },
});

function stripControlChars(input: string): string {
  // Prevent CRLF/log forging and terminal control sequences.
  // Keep printable chars + common whitespace; remove \r and other control chars.
  return input.replace(/[\u0000-\u001F\u007F]/g, (c) => (c === "\n" || c === "\t" ? c : ""));
}

function safeString(input: unknown, maxLen = 512): string | undefined {
  if (input === null || input === undefined) return undefined;
  const s = stripControlChars(String(input));
  return s.length > maxLen ? s.slice(0, maxLen) + "…" : s;
}

function safeStringArray(input: unknown, maxItems = 50): string[] | undefined {
  if (!Array.isArray(input)) return undefined;
  return input.slice(0, maxItems).map((v) => safeString(v, 128) ?? "").filter(Boolean);
}

function hashIdentifier(input: string): string {
  // Optional: use for privacy-preserving correlation (e.g., username/email).
  return crypto.createHash("sha256").update(input).digest("hex").slice(0, 16);
}

