  const event: SecurityEvent = {
    ...evt,
    ts: new Date().toISOString(),
    // sanitize common string fields
    requestId: safeString(evt.requestId, 128),
    sessionId: safeString(evt.sessionId, 128),
    userId: safeString(evt.userId, 128),
    username: safeString(evt.username, 128),
    ip: safeString(evt.ip, 64),
    userAgent: safeString(evt.userAgent, 256),
    route: safeString(evt.route, 256),
    method: safeString(evt.method, 16),
    reason: safeString(evt.reason, 256),
    fields: safeStringArray(evt.fields),
    meta: evt.meta, // keep as structured object; avoid embedding raw request bodies
