import { SecretsManagerClient, GetSecretValueCommand } from "@aws-sdk/client-secrets-manager";

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

type CachedSecret = { value: string; expiresAt: number };
const cache = new Map<string, CachedSecret>();

export async function getSecretString(secretId: string, ttlMs = 5 * 60_000): Promise<string> {
  // LLM10: bound calls to the vault via caching + TTL
  const now = Date.now();
  const cached = cache.get(secretId);
  if (cached && cached.expiresAt > now) return cached.value;

  const resp = await client.send(new GetSecretValueCommand({ SecretId: secretId }));
  if (!resp.SecretString) throw new Error("SecretString missing");

  cache.set(secretId, { value: resp.SecretString, expiresAt: now + ttlMs });
